import { Marquee as MarqueePrimitive, useMarquee, useMarqueeContext } from '@ark-ui/solid/marquee';
import { clsx } from 'clsx';
import type { ComponentProps } from 'solid-js';
import { splitProps } from 'solid-js';
import styles from './Marquee.module.css';

function MarqueeRoot(props: ComponentProps<typeof MarqueePrimitive.Root>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <MarqueePrimitive.Root
      class={clsx(styles.root, local.class)}
      {...others}
      data-slot="marquee-root"
    />
  );
}

function MarqueeRootProvider(props: ComponentProps<typeof MarqueePrimitive.RootProvider>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <MarqueePrimitive.RootProvider
      class={clsx(styles.root, local.class)}
      {...others}
      data-slot="marquee-root-provider"
    />
  );
}

function MarqueeViewport(props: ComponentProps<typeof MarqueePrimitive.Viewport>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <MarqueePrimitive.Viewport
      class={clsx(styles.viewport, local.class)}
      {...others}
      data-slot="marquee-viewport"
    />
  );
}

function MarqueeContent(props: ComponentProps<typeof MarqueePrimitive.Content>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <MarqueePrimitive.Content
      class={clsx(styles.content, local.class)}
      {...others}
      data-slot="marquee-content"
    />
  );
}

function MarqueeItem(props: ComponentProps<typeof MarqueePrimitive.Item>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <MarqueePrimitive.Item
      class={clsx(styles.item, local.class)}
      {...others}
      data-slot="marquee-item"
    />
  );
}

function MarqueeEdge(props: ComponentProps<typeof MarqueePrimitive.Edge>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <MarqueePrimitive.Edge
      class={clsx(styles.edge, local.class)}
      {...others}
      data-slot="marquee-edge"
    />
  );
}

const Marquee = Object.assign(MarqueeRoot, {
  Root: MarqueeRoot,
  RootProvider: MarqueeRootProvider,
  Context: MarqueePrimitive.Context,
  Viewport: MarqueeViewport,
  Content: MarqueeContent,
  Item: MarqueeItem,
  Edge: MarqueeEdge,
});

export { Marquee, useMarquee, useMarqueeContext };

@layer moduix.components {
  .root {
    position: relative;
    box-sizing: border-box;
    overflow: hidden;
    width: var(--moduix-marquee-width, 100%);
    height: var(--moduix-marquee-height, auto);
    color: var(--moduix-marquee-color, var(--moduix-color-foreground));

    &[data-orientation='vertical'] {
      height: var(--moduix-marquee-vertical-height, var(--moduix-marquee-height, 15rem));
    }

    &[data-paused] .content {
      animation-play-state: paused;
    }
  }

  .viewport {
    box-sizing: border-box;
    width: 100%;
    height: 100%;
  }

  .content {
    animation-name: marquee-x;
    animation-duration: var(--marquee-duration);
    animation-delay: var(--marquee-delay);
    animation-timing-function: linear;
    animation-iteration-count: var(--marquee-loop-count);

    &[data-side='top'],
    &[data-side='bottom'] {
      animation-name: marquee-y;
    }

    &[data-reverse] {
      animation-direction: reverse;
    }

    @media (prefers-reduced-motion: reduce) {
      animation: none;
    }
  }

  .item {
    box-sizing: border-box;
    flex-shrink: 0;
  }

  .edge {
    --_edge-color: var(
      --moduix-marquee-edge-color,
      var(--marquee-edge-color, var(--moduix-color-background))
    );
    --_edge-size: var(--moduix-marquee-edge-size, var(--marquee-edge-size, 20%));
    z-index: var(--moduix-marquee-edge-z-index, 1);
    pointer-events: none;

    &[data-side='start'] {
      width: var(--_edge-size);
      background: linear-gradient(to right, var(--_edge-color), transparent);

      &[dir='rtl'] {
        background: linear-gradient(to left, var(--_edge-color), transparent);
      }
    }

    &[data-side='end'] {
      width: var(--_edge-size);
      background: linear-gradient(to left, var(--_edge-color), transparent);

      &[dir='rtl'] {
        background: linear-gradient(to right, var(--_edge-color), transparent);
      }
    }

    &[data-side='top'] {
      height: var(--_edge-size);
      background: linear-gradient(to bottom, var(--_edge-color), transparent);
    }

    &[data-side='bottom'] {
      height: var(--_edge-size);
      background: linear-gradient(to top, var(--_edge-color), transparent);
    }
  }

  @keyframes marquee-x {
    from {
      transform: translateX(0%);
    }

    to {
      transform: translateX(var(--marquee-translate));
    }
  }

  @keyframes marquee-y {
    from {
      transform: translateY(0%);
    }

    to {
      transform: translateY(var(--marquee-translate));
    }
  }
}
